export interface QueueState {
  canReorder: boolean;
  tracks: string[];
}

export abstract class QueueCommand {
  abstract canRun(state: QueueState): boolean;
  abstract run(state: QueueState): readonly string[];
}

export class QueueWeaveCommand extends QueueCommand {
  canRun(state: QueueState): boolean {
    return state.canReorder && state.tracks.length >= 0;
  }

  run(state: QueueState): readonly string[] {
    if (!this.canRun(state)) throw new Error("Queue cannot be reordered");
    const reordered = [
      ...state.tracks.filter((_, index) => index % 2 === 0),
      ...state.tracks.filter((_, index) => index % 2 === 1)
    ];
    state.tracks.splice(0, state.tracks.length, ...reordered);
    return [...state.tracks];
  }
}

