import { QueueWeaveCommand } from './solution';
import type { QueueState } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(actual.length, expected.length, `${message} length`);
  for (let i = 0; i < expected.length; i += 1) equal(actual[i], expected[i], `${message} index ${i}`);
}
function throws(action: () => unknown, message: string): void {
  let failed = false;
  try { action(); } catch (error) { failed = error instanceof Error; }
  if (!failed) throw new Error(message);
}

const command = new QueueWeaveCommand();
const rejectedStates: QueueState[] = [
  { canReorder: false, tracks: ['A', 'B'] },
  { canReorder: true, tracks: [] },
  { canReorder: true, tracks: ['A'] }
];
for (const state of rejectedStates) {
  const identity = state.tracks;
  const before = [...state.tracks];
  equal(command.canRun(state), false, 'cannot run rejected state');
  throws(() => command.run(state), 'rejected run throws');
  equal(state.tracks, identity, 'rejected array identity unchanged');
  arrayEqual(state.tracks, before, 'rejected contents unchanged');
}

const tracks = ['A', 'B', 'C', 'D', 'E'];
const state: QueueState = { canReorder: true, tracks };
equal(command.canRun(state), true, 'valid state can run');
const result = command.run(state);
equal(state.tracks, tracks, 'tracks array identity preserved');
arrayEqual(state.tracks, ['A', 'C', 'E', 'B', 'D'], 'odd-sized weave');
arrayEqual(result, ['A', 'C', 'E', 'B', 'D'], 'returned snapshot');
equal(result === state.tracks, false, 'result is separate array');
(result as string[])[0] = 'changed';
equal(state.tracks[0], 'A', 'snapshot mutation does not affect state');

const special: QueueState = { canReorder: true, tracks: ['', 'x', '', 'x'] };
arrayEqual(command.run(special), ['', '', 'x', 'x'], 'empty and duplicate tracks accepted');
const pair: QueueState = { canReorder: true, tracks: ['left', 'right'] };
arrayEqual(command.run(pair), ['left', 'right'], 'two tracks deterministic');

